// Insect Swarm Sketch

let insects = [];
let numInsects = 100;

function setup() {
  pixelDensity(1);
  let cnv = createCanvas(windowWidth, windowHeight);
  cnv.style('display', 'block');
  for (let i = 0; i < numInsects; i++) {
    insects.push(new Insect());
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  background(20, 28, 38);
  for (let insect of insects) {
    insect.update();
    insect.display();
  }
}

class Insect {
  constructor() {
    this.pos = createVector(random(width), random(height));
    let angle = random(TWO_PI);
    this.vel = p5.Vector.fromAngle(angle).mult(random(1, 2));
    this.wingAngle = random(TWO_PI);
    this.wingSpeed = random(0.1, 0.3);
    this.size = random(8, 16);
    this.color = color(random(180, 255), random(120, 200), random(50, 100), 200);
  }

  update() {
    this.wingAngle += this.wingSpeed;
    this.pos.add(this.vel);
    if (this.pos.x < 0 || this.pos.x > width) this.vel.x *= -1;
    if (this.pos.y < 0 || this.pos.y > height) this.vel.y *= -1;
    // Mouse repulsion
    let m = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let d = p5.Vector.dist(this.pos, m);
    if (d < 100) {
      let flee = p5.Vector.sub(this.pos, m).setMag(2);
      this.vel.add(flee);
      this.vel.limit(3);
    }
  }

  display() {
    push();
    translate(this.pos.x, this.pos.y);
    rotate(this.vel.heading());
    noStroke();
    fill(this.color);
    // Body
    ellipse(0, 0, this.size * 1.2, this.size * 0.8);
    // Wings
    let wingOffset = this.size * 0.5;
    let wAngle = sin(this.wingAngle) * PI / 6;
    push();
    rotate(wAngle);
    ellipse(-wingOffset, 0, this.size, this.size * 0.6);
    pop();
    push();
    rotate(-wAngle);
    ellipse(-wingOffset, 0, this.size, this.size * 0.6);
    pop();
    pop();
  }
}


